(async()=>{const results=[];for(const[engine,type]of[['chromium',chromium],['webkit',webkit]]){const b=await type.launch({headless:true});try{for(const width of[320,393,1366]){let r;try{r=await run(b,engine,width);}catch(e){r={pass:false,engine,width,error:e.stack};process.exitCode=1;}results.push(r);console.log(JSON.stringify(r));fs.writeFileSync(out+'/period-result.json',JSON.stringify({pass:results.length===6&&results.every(x=>x.pass),results},null,2));}}finally{await b.close();}}})().catch(e=>{console.error(e);process.exitCode=1;});
